import { desc, eq, sql } from "drizzle-orm";
import { AdminNav } from "@/components/admin/admin-nav";
import { db } from "@/db";
import { supportTickets, users } from "@/db/schema";
import { requireAdmin } from "@/lib/admin/authorization";
import { getQuestionBankSettings } from "@/lib/admin/question-bank-settings";
import { getPreferences } from "@/lib/i18n/get-translations";
import { updateTicketStatus } from "./actions";
const categoryVi:Record<string,string>={TECHNICAL:"Lỗi kỹ thuật",CONTENT:"Nội dung học tập",PAYMENT:"Tài khoản / thanh toán",SUGGESTION:"Góp ý tính năng",OTHER:"Khác"};
export default async function AdminSupportPage({searchParams}:{searchParams:Promise<{status?:string}>}){const actor=await requireAdmin("USER_READ"),[prefs,query,settings]=await Promise.all([getPreferences(actor.id),searchParams,getQuestionBankSettings()]),vi=prefs.interfaceLanguage==="vi",selected=["NEW","IN_PROGRESS","RESOLVED"].includes(query.status??"")?query.status!:"NEW";const rows=await db.select({ticket:supportTickets,accountEmail:users.email,overdue:sql<boolean>`${supportTickets.status} = 'NEW' and ${supportTickets.createdAt} < now() - (${settings.supportResponseTargetHours} * interval '1 hour')`}).from(supportTickets).leftJoin(users,eq(users.id,supportTickets.userId)).where(eq(supportTickets.status,selected)).orderBy(desc(supportTickets.createdAt)).limit(100);return <main className="min-h-screen bg-slate-50 px-4 py-6 text-slate-900 sm:px-6"><div className="mx-auto max-w-6xl"><AdminNav locale={prefs.interfaceLanguage}/><header className="mt-8"><p className="text-xs font-black uppercase tracking-[.18em] text-teal-700">{vi?"Vận hành & hỗ trợ":"Operations & support"}</p><h1 className="mt-2 text-3xl font-black">{vi?"Phản hồi người dùng":"User feedback"}</h1><p className="mt-2 text-slate-600">{vi?`Theo dõi yêu cầu hỗ trợ; mục tiêu phản hồi ticket mới trong ${settings.supportResponseTargetHours} giờ.`:`Review support requests; target a first response to new tickets within ${settings.supportResponseTargetHours} hours.`}</p></header><nav className="mt-6 flex flex-wrap gap-2" aria-label="Feedback status">{["NEW","IN_PROGRESS","RESOLVED"].map(status=><a className={`rounded-full px-4 py-2 text-sm font-bold ${selected===status?"bg-slate-900 text-white":"border bg-white text-slate-600"}`} href={`?status=${status}`} key={status}>{status==="NEW"?(vi?"Mới":"New"):status==="IN_PROGRESS"?(vi?"Đang xử lý":"In progress"):(vi?"Đã xử lý":"Resolved")}</a>)}</nav><div className="mt-6 grid gap-4">{rows.map(({ticket,accountEmail,overdue})=><article className={`rounded-2xl border bg-white p-5 shadow-sm ${overdue?"border-rose-300":"border-slate-200"}`} key={ticket.id}><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex flex-wrap gap-2"><span className="rounded-full bg-teal-50 px-3 py-1 text-xs font-black text-teal-800">{vi?categoryVi[ticket.category]:ticket.category}</span>{overdue?<span className="rounded-full bg-rose-100 px-3 py-1 text-xs font-black text-rose-800">{vi?"Quá SLA phản hồi":"Response SLA overdue"}</span>:null}</div><h2 className="mt-3 text-lg font-black">{ticket.subject}</h2><p className="mt-1 text-sm text-slate-500">{ticket.email}{accountEmail?` · ${vi?"Tài khoản":"Account"}: ${accountEmail}`:""} · {ticket.createdAt.toLocaleString(vi?"vi-VN":"en-US",{timeZone:"Asia/Ho_Chi_Minh"})}</p></div><form action={updateTicketStatus} className="flex gap-2"><input name="id" type="hidden" value={ticket.id}/><select className="min-h-10 rounded-lg border px-3 text-sm" defaultValue={ticket.status} name="status"><option value="NEW">{vi?"Mới":"New"}</option><option value="IN_PROGRESS">{vi?"Đang xử lý":"In progress"}</option><option value="RESOLVED">{vi?"Đã xử lý":"Resolved"}</option></select><button className="rounded-lg bg-teal-700 px-3 text-sm font-bold text-white">{vi?"Lưu":"Save"}</button></form></div><p className="mt-4 whitespace-pre-wrap rounded-xl bg-slate-50 p-4 text-sm leading-6">{ticket.message}</p>{ticket.pageUrl?<a className="mt-3 block break-all text-sm font-bold text-teal-700 underline" href={ticket.pageUrl} rel="noreferrer" target="_blank">{ticket.pageUrl}</a>:null}</article>)}{!rows.length?<div className="rounded-2xl border border-dashed bg-white p-8 text-center text-slate-600">{vi?"Không có phản hồi ở trạng thái này.":"No feedback in this status."}</div>:null}</div></div></main>}
